WITH flagged AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL '1' HOUR THEN 1 ELSE 0 END AS is_new_session FROM device_readings), sessions_device_readings AS (SELECT id, device_code, reading_ts, humidity, pressure, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT id, device_code, reading_ts, CASE WHEN device_code RLIKE '^(DV-01|DV-02)$' THEN 'PRIORITY' WHEN device_code RLIKE '^(DV-03|DV-04)$' THEN 'EXTENDED' ELSE 'GROUP_B' END AS device_code_zone FROM sessions_device_readings ORDER BY device_code DESC, id LIMIT 20;
